import React, { useState, useEffect } from 'react';
import Calendar from 'react-calendar';
import { tasksAPI, goalsAPI } from '../utils/api';
import { Calendar as CalendarIcon, CheckSquare, Target } from 'lucide-react';
import 'react-calendar/dist/Calendar.css';

const CalendarPage = () => {
  const [date, setDate] = useState(new Date());
  const [tasks, setTasks] = useState([]);
  const [goals, setGoals] = useState([]);
  const [selectedDateEvents, setSelectedDateEvents] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchData();
  }, []);

  useEffect(() => {
    filterEventsByDate(date);
  }, [date, tasks, goals]);

  const fetchData = async () => {
    try {
      const [tasksRes, goalsRes] = await Promise.all([
        tasksAPI.getAll(),
        goalsAPI.getAll()
      ]);
      setTasks(tasksRes.data);
      setGoals(goalsRes.data);
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const filterEventsByDate = (selectedDate) => {
    const dateStr = selectedDate.toDateString();

    const dayTasks = tasks.filter(task => 
      new Date(task.dueDate).toDateString() === dateStr
    );

    const dayGoals = goals.filter(goal => 
      new Date(goal.deadline).toDateString() === dateStr
    );

    setSelectedDateEvents([
      ...dayTasks.map(task => ({ ...task, type: 'task' })),
      ...dayGoals.map(goal => ({ ...goal, type: 'goal' }))
    ]);
  };

  const tileContent = ({ date, view }) => {
    if (view === 'month') {
      const dateStr = date.toDateString();
      const dayTasks = tasks.filter(task => 
        new Date(task.dueDate).toDateString() === dateStr
      );
      const dayGoals = goals.filter(goal => 
        new Date(goal.deadline).toDateString() === dateStr
      );

      const totalEvents = dayTasks.length + dayGoals.length;

      if (totalEvents > 0) {
        return (
          <div className="flex justify-center">
            <div className="w-2 h-2 bg-primary-600 rounded-full"></div>
          </div>
        );
      }
    }
    return null;
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      <div className="max-w-7xl mx-auto py-6 px-4 sm:px-6 lg:px-8">
        <div className="flex items-center mb-6">
          <CalendarIcon className="w-8 h-8 text-primary-600 mr-3" />
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Calendar</h1>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Calendar */}
          <div className="lg:col-span-2">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
              <Calendar
                onChange={setDate}
                value={date}
                tileContent={tileContent}
                className="w-full border-none"
              />
            </div>
          </div>

          {/* Events for Selected Date */}
          <div className="lg:col-span-1">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4">
                Events for {date.toLocaleDateString()}
              </h2>

              {selectedDateEvents.length > 0 ? (
                <div className="space-y-3">
                  {selectedDateEvents.map((event) => (
                    <div
                      key={`${event.type}-${event._id}`}
                      className="p-3 border border-gray-200 dark:border-gray-700 rounded-lg"
                    >
                      <div className="flex items-start">
                        {event.type === 'task' ? (
                          <CheckSquare className="w-5 h-5 text-blue-500 mr-2 mt-0.5" />
                        ) : (
                          <Target className="w-5 h-5 text-green-500 mr-2 mt-0.5" />
                        )}
                        <div className="flex-1">
                          <h3 className="font-medium text-gray-900 dark:text-white">
                            {event.title}
                          </h3>
                          {event.description && (
                            <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                              {event.description}
                            </p>
                          )}
                          <div className="flex items-center mt-2">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                              event.type === 'task' 
                                ? 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200'
                                : 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
                            }`}>
                              {event.type === 'task' ? 'Task' : 'Goal'}
                            </span>
                            {event.type === 'task' && (
                              <span className={`ml-2 px-2 py-1 rounded-full text-xs font-medium ${
                                event.priority === 'high' ? 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' :
                                event.priority === 'medium' ? 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200' :
                                'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
                              }`}>
                                {event.priority}
                              </span>
                            )}
                            {event.type === 'goal' && (
                              <span className="ml-2 text-xs text-gray-600 dark:text-gray-400">
                                {event.progress}% complete
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <CalendarIcon className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-600 dark:text-gray-400">
                    No events scheduled for this date
                  </p>
                </div>
              )}
            </div>

            {/* Quick Stats */}
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 mt-6">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                This Month
              </h3>
              <div className="space-y-3">
                <div className="flex justify-between items-center">
                  <span className="text-gray-600 dark:text-gray-400">Total Tasks</span>
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {tasks.filter(task => 
                      new Date(task.dueDate).getMonth() === date.getMonth() &&
                      new Date(task.dueDate).getFullYear() === date.getFullYear()
                    ).length}
                  </span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600 dark:text-gray-400">Total Goals</span>
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {goals.filter(goal => 
                      new Date(goal.deadline).getMonth() === date.getMonth() &&
                      new Date(goal.deadline).getFullYear() === date.getFullYear()
                    ).length}
                  </span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-gray-600 dark:text-gray-400">Completed Tasks</span>
                  <span className="font-semibold text-gray-900 dark:text-white">
                    {tasks.filter(task => 
                      task.status === 'completed' &&
                      new Date(task.dueDate).getMonth() === date.getMonth() &&
                      new Date(task.dueDate).getFullYear() === date.getFullYear()
                    ).length}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CalendarPage;
